-- General-item store catalogue (migration 0156), generated by
-- tools/import_lsb_store_items.py from LandSandBoat's item_basic / item_usable
-- tables and the retail client names for equipment-like items.
--
-- The Armory (migration 111) only imports equipment.  This adds the other
-- things a character buys in bulk: ninja tools, Call Beast jugs, pet food,
-- potions, food, ingredients, crafting materials, crystals, scrolls, arrows
-- and furnishings.  `category` is the Items tab filter; equipment rows keep
-- an empty category and stay in the Armory.
--
-- Price is deterministic: 10 times the NPC resale value, or 1,000 gil when
-- the item has no resale value (Reraizer, quest spell scrolls, event food).
-- Existing rows keep their hand-written name, equip slot, model, stack size and
-- usable bit; only the category, price and Rare/Ex bits are refreshed.

ALTER TABLE items ADD COLUMN category TEXT NOT NULL DEFAULT '';

